	private final ServerTFBossBar bossEvent;
	private final NonNullList<ItemStack> dyingInventory = NonNullList.withSize(27, ItemStack.EMPTY);

	protected BaseTFBoss(EntityType<? extends Monster> type, Level level) {
		super(type, level);
